-- Empty-volume PostgreSQL baseline for a clean installation.

CREATE TABLE users (id uuid PRIMARY KEY, telegram_user_id bigint NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE user_profiles (user_id uuid PRIMARY KEY REFERENCES users(id), username text, first_name text, last_name text, language_code text NOT NULL DEFAULT 'ru', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallets (id uuid PRIMARY KEY, user_id uuid NOT NULL UNIQUE REFERENCES users(id), currency_code char(3) NOT NULL, balance_minor bigint NOT NULL DEFAULT 0 CHECK (balance_minor >= 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles (id uuid PRIMARY KEY, code text NOT NULL UNIQUE, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_roles (user_id uuid NOT NULL REFERENCES users(id), role_id uuid NOT NULL REFERENCES roles(id), granted_by_user_id uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, role_id));
CREATE TABLE admin_sessions (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), session_hash bytea NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE TABLE user_sessions (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), token_hash bytea NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE INDEX user_sessions_active_idx ON user_sessions (token_hash, expires_at) WHERE revoked_at IS NULL;
CREATE TABLE app_settings (key text PRIMARY KEY, value jsonb NOT NULL, updated_by_user_id uuid REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE brands (id uuid PRIMARY KEY, name text NOT NULL, support_url text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tariffs (id uuid PRIMARY KEY, code text NOT NULL UNIQUE, name jsonb NOT NULL, description jsonb NOT NULL DEFAULT '{}'::jsonb, duration_seconds bigint CHECK (duration_seconds IS NULL OR duration_seconds > 0), traffic_bytes bigint CHECK (traffic_bytes IS NULL OR traffic_bytes >= 0), position integer NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tariff_prices (id uuid PRIMARY KEY, tariff_id uuid NOT NULL REFERENCES tariffs(id), currency_code char(3) NOT NULL, amount_minor bigint NOT NULL CHECK (amount_minor >= 0), is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX tariff_prices_active_currency_idx ON tariff_prices (tariff_id, currency_code) WHERE is_active;
CREATE TABLE invoices (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), provider text NOT NULL, provider_invoice_id text, purpose text NOT NULL CHECK (purpose IN ('wallet_top_up', 'direct_purchase')), status text NOT NULL CHECK (status IN ('pending', 'paid', 'expired', 'cancelled')), currency_code char(3) NOT NULL, amount_minor bigint NOT NULL CHECK (amount_minor >= 0), tariff_id uuid REFERENCES tariffs(id), expires_at timestamptz NOT NULL, paid_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (provider, provider_invoice_id));
CREATE INDEX invoices_pending_idx ON invoices (provider, expires_at) WHERE status = 'pending';
CREATE INDEX invoices_user_idx ON invoices (user_id, created_at DESC);
CREATE TABLE payment_attempts (id uuid PRIMARY KEY, invoice_id uuid NOT NULL REFERENCES invoices(id), provider text NOT NULL, provider_payment_id text, status text NOT NULL, raw_response jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (provider, provider_payment_id));
CREATE TABLE payment_provider_settings (provider_code text PRIMARY KEY CHECK (provider_code IN ('crypto_pay', 'anore', 'telegram_stars')), is_enabled boolean NOT NULL DEFAULT false, public_settings jsonb NOT NULL DEFAULT '{}'::jsonb, updated_by_user_id uuid REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_webhook_events (id uuid PRIMARY KEY, provider text NOT NULL, provider_event_id text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, payload jsonb NOT NULL, processing_error text, UNIQUE (provider, provider_event_id));
CREATE TABLE vpn_accounts (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), provider text NOT NULL, external_id text NOT NULL, encrypted_access_url bytea, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (provider, external_id), UNIQUE (user_id, provider));
CREATE TABLE subscriptions (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), tariff_id uuid REFERENCES tariffs(id), vpn_account_id uuid REFERENCES vpn_accounts(id), source_invoice_id uuid UNIQUE REFERENCES invoices(id), status text NOT NULL CHECK (status IN ('provisioning_pending', 'active', 'suspended', 'expired', 'failed')), starts_at timestamptz, expires_at timestamptz, traffic_bytes bigint CHECK (traffic_bytes IS NULL OR traffic_bytes >= 0), is_trial boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX subscriptions_user_idx ON subscriptions (user_id, created_at DESC);
CREATE TABLE subscription_events (id uuid PRIMARY KEY, subscription_id uuid NOT NULL REFERENCES subscriptions(id), event_type text NOT NULL, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events (id uuid PRIMARY KEY, aggregate_type text NOT NULL, aggregate_id uuid NOT NULL, event_type text NOT NULL, payload jsonb NOT NULL, attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, lock_owner text, processed_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_events_pending_idx ON outbox_events (available_at, created_at) WHERE processed_at IS NULL;
CREATE TABLE notifications (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), kind text NOT NULL, locale text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'sent', 'failed', 'cancelled')), attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notifications_pending_idx ON notifications (available_at, created_at) WHERE status = 'pending';
CREATE TABLE promo_codes (id uuid PRIMARY KEY, code text NOT NULL UNIQUE, kind text NOT NULL CHECK (kind IN ('balance', 'discount')), amount_minor bigint, discount_percent smallint, maximum_redemptions integer, redeemed_count integer NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true, starts_at timestamptz, ends_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CHECK ((kind = 'balance' AND amount_minor IS NOT NULL AND amount_minor > 0 AND discount_percent IS NULL) OR (kind = 'discount' AND discount_percent BETWEEN 0 AND 100 AND amount_minor IS NULL)), CHECK (maximum_redemptions IS NULL OR maximum_redemptions > 0));
CREATE TABLE wallet_transactions (id uuid PRIMARY KEY, wallet_id uuid NOT NULL REFERENCES wallets(id), amount_minor bigint NOT NULL, currency_code char(3) NOT NULL, kind text NOT NULL, reference_type text NOT NULL, reference_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (reference_type, reference_id, kind));
CREATE TABLE promo_redemptions (id uuid PRIMARY KEY, promo_code_id uuid NOT NULL REFERENCES promo_codes(id), user_id uuid NOT NULL REFERENCES users(id), invoice_id uuid REFERENCES invoices(id), wallet_transaction_id uuid REFERENCES wallet_transactions(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (promo_code_id, user_id));
CREATE TABLE referrals (id uuid PRIMARY KEY, referrer_user_id uuid NOT NULL REFERENCES users(id), referred_user_id uuid NOT NULL UNIQUE REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), CHECK (referrer_user_id <> referred_user_id));
CREATE TABLE referral_rewards (id uuid PRIMARY KEY, referral_id uuid NOT NULL REFERENCES referrals(id), source_invoice_id uuid NOT NULL UNIQUE REFERENCES invoices(id), wallet_transaction_id uuid NOT NULL UNIQUE REFERENCES wallet_transactions(id), amount_minor bigint NOT NULL CHECK (amount_minor > 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_keys (key uuid PRIMARY KEY, scope text NOT NULL, request_hash bytea NOT NULL, response_status smallint, response_body jsonb, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
CREATE TABLE audit_log (id uuid PRIMARY KEY, actor_user_id uuid REFERENCES users(id), action text NOT NULL, target_type text NOT NULL, target_id uuid, before_value jsonb, after_value jsonb, correlation_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_log_target_idx ON audit_log (target_type, target_id, created_at DESC);
CREATE TABLE admin_accounts (user_id uuid PRIMARY KEY REFERENCES users(id), login text NOT NULL UNIQUE, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), last_login_at timestamptz);
